class Solution {
  public int numberOfPermutations(int n, int[][] requirements) {
    final int MOD = 1_000_000_007;
    int[] required = new int[n];
    java.util.Arrays.fill(required, -1);
    int max = 0;
    for (int[] r : requirements) {
      required[r[0]] = r[1];
      max = Math.max(max, r[1]);
    }
    int[][] dp = new int[n + 1][max + 1];
    dp[0][0] = 1;
    for (int length = 1; length <= n; length++) {
      int end = length - 1;
      long window = 0;
      for (int inv = 0; inv <= max; inv++) {
        window += dp[length - 1][inv];
        if (inv >= length) window -= dp[length - 1][inv - length];
        dp[length][inv] = (int) (window % MOD);
      }
      if (required[end] >= 0)
        for (int inv = 0; inv <= max; inv++) if (inv != required[end]) dp[length][inv] = 0;
    }
    return required[n - 1] >= 0 ? dp[n][required[n - 1]] : 0;
  }
}
